<?php require 'config.php';require_login();$title='Record a sale';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$mid=(int)$_POST['medicine_id'];$qty=(int)$_POST['quantity'];try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT * FROM medicines WHERE id=? FOR UPDATE');$q->execute([$mid]);$m=$q->fetch();if(!$m||$qty<1||$m['quantity']<$qty)throw new RuntimeException('Insufficient stock or invalid quantity.');if($m['expiry_date']<date('Y-m-d'))throw new RuntimeException('This batch is expired and cannot be sold.');$total=$qty*(float)$m['price'];$pdo->prepare('INSERT INTO sales(medicine_id,quantity,unit_price,total_amount,customer_name) VALUES(?,?,?,?,?)')->execute([$mid,$qty,$m['price'],$total,trim($_POST['customer_name'])]);$pdo->prepare('UPDATE medicines SET quantity=quantity-? WHERE id=?')->execute([$qty,$mid]);$pdo->commit();flash('Sale recorded. Inventory has been updated.');go('sales_history.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$meds=$pdo->query('SELECT id,name,batch_no,quantity,price,expiry_date FROM medicines WHERE quantity>0 AND expiry_date>=CURDATE() ORDER BY name')->fetchAll();require 'partials/header.php';?>
<div class="pagehead"><div><div class="eyebrow">POINT OF SALE</div><h1>Record a sale</h1><p class="sub">Create a sale and automatically update medicine stock.</p></div></div>
<div class="card" style="max-width:760px"><h2>Sale details</h2><?php if($error):?><div class="alert error" style="margin-top:15px"><?=h($error)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="formgrid" style="margin-top:15px"><div class="field full"><label>Medicine / batch</label><select name="medicine_id" required><?php foreach($meds as $m):?><option value="<?=$m['id']?>"><?=h($m['name'])?> · Batch <?=h($m['batch_no'])?> · <?=$m['quantity']?> available · ₹<?=number_format((float)$m['price'],2)?></option><?php endforeach?></select></div><div class="field"><label>Quantity</label><input type="number" name="quantity" min="1" required></div><div class="field"><label>Customer name (optional)</label><input name="customer_name" placeholder="Walk-in customer"></div></div><div class="actions"><button class="btn">Confirm sale</button><a class="btn secondary" href="sales_history.php">View sales history</a></div></form></div><?php require 'partials/footer.php';?>
